mapper.insert:
INSERT INTO com01_relate_appr ( com01_relate_appr_id, com01_key_table, com01_key_table_id, com01_appr_id )
SELECT #{relateApprId}, #{keyTable}, #{keyTableId}, apr01_appr_id
  FROM apr01_appr
 WHERE apr01_appr_id = #{apprId}
   AND apr01_company_id = #{companyId}

mapper.delete:
DELETE FROM com01_relate_appr
 WHERE com01_relate_appr_id = #{relateApprId}
   AND EXISTS ( SELECT 1 FROM apr01_appr WHERE apr01_appr_id = com01_appr_id AND apr01_company_id = #{companyId} )

mapper.select:
SELECT COALESCE(sys01_erp_product_cd, '') <> 'S1'
  FROM sys01_company
 WHERE sys01_company_id = #{companyId}
